// Des: Car page parser: HTML page (or social record) to one Car row
// Flo: split html to lines > label lines give fields (first hit wins, stop at similar-cars) > price from JSON-LD, price-only line or title > make/model from URL slug, labels or title > normalize > class, powertrain, seller kind
// I/O: url + html + arena (caller) > Car; unknown stays empty (text), 0 (numbers) or -1 (km); individual seller names are dropped, only dealer names and the phone digits are kept
// ===================================================================
const std = @import("std"); const text = @import("pa-carz-text.zig"); const norm = @import("pa-carz-norm.zig"); const labl = @import("pa-carz-labl.zig"); const help = @import("pa-carz-help.zig"); const cont = @import("pa-cont-pars.zig"); const typz = @import("pa-carz-type.zig"); const soci = @import("pa-carz-soci.zig");
pub const Carz = typz.Carz; pub const VERS = typz.VERS; pub const hostOfzz = help.hostOfzz; pub const lidzOfzz = help.lidzOfzz;
const DLER = [_][]const u8{ "showroom", "salon", "auto", "đại lý", "công ty", "cửa hàng", "motor", "ô tô", "car", "group", "trading", "dealer", "cty", "thaco", "oto" };
pub fn carzPars(aren: std.mem.Allocator, urlz: []const u8, html: []const u8, nowy: i64) !Carz { if (soci.sociHost(hostOfzz(urlz)) and soci.isReco(html)) return soci.sociPars(aren, urlz, html, nowy); const page = try text.pageSpli(aren, html); var carz: Carz = .{ .urlz = urlz, .site = hostOfzz(urlz), .lidz = lidzOfzz(urlz), .titl = help.cleaTitl(page.titl) }; var xtrz: std.ArrayList(u8) = .empty; var xcnt: u32 = 0; var seen: std.StringHashMapUnmanaged(void) = .empty; var descDone = false; var idxz: usize = 0; const lins = page.lins;
    while (idxz < lins.len) : (idxz += 1) { const line = lins[idxz]; if (labl.iszzSimi(line)) break; if (idxz < 80 and !carz.gone and labl.iszzDead(line)) carz.gone = true; if (!descDone and labl.iszzDesc(line)) { descDone = true; var bufz: std.ArrayList(u8) = .empty; var jdxz = idxz + 1; while (jdxz < lins.len and bufz.items.len < 1200 and jdxz < idxz + 13) : (jdxz += 1) { if (labl.iszzStop(lins[jdxz])) break; if (bufz.items.len > 0) try bufz.append(aren, ' '); try bufz.appendSlice(aren, lins[jdxz]); } carz.text = try bufz.toOwnedSlice(aren); idxz = jdxz - 1; continue; } const hitz = labl.lablSpli(line); const fidz = labl.labeFind(hitz.labl); const nexz = if (idxz + 1 < lins.len) lins[idxz + 1] else ""; if (fidz == .none) continue; var valu: []const u8 = hitz.rest; if (valu.len == 0 and nexz.len > 0 and nexz.len <= 120 and labl.labeFind(labl.lablSpli(nexz).labl) == .none) valu = nexz; if (valu.len == 0 or labl.junkValz(valu)) continue; switch (fidz) { .none, .dist => {}, .xtra => { if (!seen.contains(hitz.labl)) { try seen.put(aren, hitz.labl, {}); try help.xtraAddz(aren, &xtrz, &xcnt, hitz.labl, valu); } }, .year => { if (carz.year == 0) carz.year = norm.normYear(valu); }, .orig => help.setzStrz(&carz.orig, valu), .body => help.setzStrz(&carz.body, valu), .gear => { if (carz.gear.len == 0) carz.gear = norm.normGear(valu); }, .engn => help.setzStrz(&carz.engn, valu), .fuel => help.setzStrz(&carz.fuel, valu), .driv => help.setzStrz(&carz.driv, valu), .colx => help.setzStrz(&carz.colx, valu), .coli => help.setzStrz(&carz.coli, valu), .seat => { if (carz.seat == 0) carz.seat = help.smalNumz(valu); }, .door => { if (carz.door == 0) carz.door = help.smalNumz(valu); }, .kmzz => { if (carz.kmzz < 0) { carz.kmzz = norm.normKmzz(valu); if (carz.kmzz < 0 and carz.cond.len == 0) carz.cond = norm.normCond(valu); } }, .cond => { if (carz.cond.len == 0) carz.cond = norm.normCond(valu); }, .owns => { if (carz.owns == 0) carz.owns = help.smalNumz(valu); }, .make => help.setzStrz(&carz.make, valu), .modl => help.setzStrz(&carz.modl, valu), .trim => help.setzStrz(&carz.trim, valu), .prov => help.setzStrz(&carz.prov, valu), .post => { if (carz.post == 0) carz.post = help.dateMill(valu); }, .phon => { if (!norm.hasz(valu, "email")) help.setzStrz(&carz.phon, valu); }, .sell => { if (carz.cnam.len == 0) carz.cnam = valu; if (carz.sell.len == 0) { var dlrz = false; for (DLER) |kwrd| { if (norm.hasz(valu, kwrd)) dlrz = true; } if (dlrz) { carz.sell = "dealer"; carz.shop = valu; } else carz.sell = "private"; } } } }
    if (xcnt > 0) { try xtrz.append(aren, '}'); carz.xtra = try xtrz.toOwnedSlice(aren); }
    var jbuf: [32]u8 = undefined; var jprc: i64 = 0; var jkmz: i64 = -1; var jyea: i64 = 0; for (page.ldjs) |blob| { if (!(std.mem.indexOf(u8, blob, "\"Car\"") != null or std.mem.indexOf(u8, blob, "\"Product\"") != null or std.mem.indexOf(u8, blob, "\"Vehicle\"") != null)) continue; if (jprc == 0) { const rawz = help.jsonRawz(blob, "price", &jbuf); if (rawz.len > 0) jprc = norm.normPric(rawz); if (jprc == 0) jprc = std.fmt.parseInt(i64, rawz, 10) catch 0; } if (jkmz < 0) { var kbuf: [32]u8 = undefined; const rawz = help.jsonRawz(blob, "mileageFromOdometer", &kbuf); if (rawz.len > 0) jkmz = norm.normKmzz(rawz); } if (jyea == 0) { var ybuf: [32]u8 = undefined; jyea = norm.normYear(help.jsonRawz(blob, "vehicleModelDate", &ybuf)); } }
    if (jprc >= 1_000_000) carz.pric = jprc; if (carz.pric == 0) { for (lins, 0..) |line, jdxz| { if (jdxz > 400) break; if (help.pricOnly(line)) { const valu = norm.normPric(line); if (valu > 0) { carz.pric = valu; break; } } } } if (carz.pric == 0) carz.pric = help.titlPric(carz.titl); if (carz.kmzz < 0) carz.kmzz = help.kmzzScan(carz.titl); if (carz.kmzz < 0) carz.kmzz = help.kmzzScan(carz.text);
    if (carz.kmzz < 0 and jkmz >= 0) carz.kmzz = jkmz; if (carz.year == 0) carz.year = if (jyea != 0) jyea else norm.normYear(carz.titl);
    help.titlModl(&carz, carz.titl); if (carz.make.len == 0 and std.mem.eql(u8, carz.site, "bonbanh.com")) try help.slugBonb(aren, &carz);
    if (carz.cond.len == 0 and norm.hasz(carz.titl, "xe mới")) carz.cond = "new"; if (std.mem.eql(u8, carz.cond, "new") and carz.year > 0 and carz.year < nowy - 1) carz.cond = ""; if (carz.cond.len == 0 and carz.kmzz >= 500) carz.cond = "used"; if (carz.gear.len == 0) carz.gear = norm.normGear(carz.titl);
    const fupo = try std.fmt.allocPrint(aren, "{s} {s}", .{ carz.fuel, carz.engn }); carz.powr = norm.normPowr(fupo); if (carz.powr.len == 0) carz.powr = norm.normPowr(carz.titl);
    if (carz.prov.len == 0) { var jdxz: usize = 0; while (jdxz < lins.len and jdxz < 80 and carz.prov.len == 0) : (jdxz += 1) { if (lins[jdxz].len > 100) continue; for (labl.PROV) |prov| { if (std.mem.indexOf(u8, lins[jdxz], prov) != null) { carz.prov = prov; break; } } } }
    if (carz.phon.len == 0) carz.phon = try help.phonScan(aren, carz.text); const desz = carz.text; carz.text = try help.maskPhon(aren, carz.text); try cont.contFind(aren, &carz, lins, desz); if (labl.junkValz(carz.trim)) carz.trim = ""; if (labl.junkValz(carz.modl)) carz.modl = ""; carz.clsz = help.clasOfzz(&carz); return carz; }
